CREATE OR REPLACE FUNCTION calculate_abandonment_rate(cat_name TEXT, start_date DATE, end_date DATE)
RETURNS NUMERIC AS $$
DECLARE
  total_items INT;
  abandoned_items INT;
  rate NUMERIC;
BEGIN
  SELECT COUNT(*) INTO total_items
  FROM cart_additions ca
  JOIN product_catalog pc ON ca.product_id = pc.product_id
  WHERE pc.category = cat_name
    AND ca.added_at >= start_date
    AND ca.added_at <= end_date;

  IF total_items = 0 THEN
    RETURN 0.00;
  END IF;

  SELECT COUNT(*) INTO abandoned_items
  FROM cart_additions ca
  JOIN product_catalog pc ON ca.product_id = pc.product_id
  LEFT JOIN purchases p ON ca.customer_id = p.customer_id
    AND ca.product_id = p.product_id
    AND p.purchased_at >= start_date
    AND p.purchased_at <= end_date
  WHERE pc.category = cat_name
    AND ca.added_at >= start_date
    AND ca.added_at <= end_date
    AND p.purchase_id IS NULL;

  rate := ROUND((abandoned_items::NUMERIC / total_items::NUMERIC) * 100, 2);
  RETURN rate;
END;
$$ LANGUAGE plpgsql;

SELECT calculate_abandonment_rate('Footwear', DATE '2024-01-01', DATE '2024-01-31') AS result;
